import { getSession } from "@/lib/auth"; import { query } from "@/lib/db"; import { Brand } from "@/components/Brand"; import { DeleteCourseButton, LogoutButton, BackButton } from "@/components/AdminControls";
export default async function AdminCourses({searchParams}:{searchParams:Promise<{q?:string}>}){const s=await getSession();if(!s||s.role!=="admin")return <main className="login-page"><div className="login-card"><Brand/><h1>Admin access</h1><a className="btn btn-primary" href="/login">Login</a></div></main>;const{q=""}=await searchParams;const term=q.trim();const r=await query(`SELECT id,title,slug,price,is_published FROM courses ${term?"WHERE title LIKE $1 OR slug LIKE $1":""} ORDER BY created_at DESC`,term?[`%${term}%`]:[]);return <div className="dashboard"><aside className="sidebar"><Brand/><nav><a href="/admin">⌂ Dashboard</a><a className="active" href="/admin/courses">▦ Courses</a><a>◉ Students</a><a>◉ Teachers</a><a>▶ Videos</a><a>₹ Payments</a><a>☑ Tests</a><a>● Feedback</a><a>◫ Reports</a><a>⚙ Settings</a></nav><LogoutButton/></aside><main className="main"><div className="section-head"><div><span className="eyebrow">CONTENT MANAGEMENT</span><h1>Courses</h1><p className="muted">Create, search, edit and delete course content.</p></div><div className="actions"><BackButton/><a className="btn btn-primary" href="/admin/courses/new">+ Add Course</a></div></div><form className="searchbar" method="get"><span>⌕</span><input name="q" defaultValue={term} placeholder="Search courses by title or slug…"/><button className="btn btn-secondary" type="submit">Search</button>{term&&<a className="btn btn-secondary" href="/admin/courses">Clear</a>}</form><div className="panel"><table className="table"><thead><tr><th>Course</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody>{r.rows.map((c:any)=><tr key={String(c.id)}><td><b>{String(c.title)}</b><br/><span className="muted">{String(c.slug)}</span></td><td>₹{String(c.price)}</td><td>{c.is_published?<span className="tag">Published</span>:<span className="tag draft-tag">Draft</span>}</td><td><div className="actions"><a className="btn btn-secondary" href={`/admin/content/${c.id}`}>Manage</a><a className="btn btn-secondary" href={`/admin/courses/${c.id}/edit`}>Edit</a><DeleteCourseButton id={String(c.id)} title={String(c.title)}/></div></td></tr>)}{!r.rows.length&&<tr><td colSpan={4} className="empty">No courses found.</td></tr>}</tbody></table></div></main></div>}
